```cpp
Mesh<Point, double> power_diagram_faces(
  RT const &rt,
  double threshold)
{
  Mesh<Point, double> mesh;

  // Iterate over all finite edges
  for (auto eit = rt.finite_edges_begin(); eit != rt.finite_edges_end(); ++eit) {
    // Skip small edges based on threshold
    if (is_small_edge(rt, *eit, threshold)) {
      continue;
    }

    // Get the two cells incident to this edge
    RT::Cell_handle c1 = eit->first;
    RT::Cell_handle c2 = c1->neighbor(eit->second);

    // Collect vertices from both cells (skip the edge vertices to form face polygon)
    std::vector<unsigned> face_vertices;

    // Get the two vertices that form the edge
    unsigned v1 = eit->first->vertex(eit->second)->index();
    unsigned v2 = eit->first->vertex(rt.vertex_triple_index(eit->second, eit->third))->index();

    // Add all vertices from both cells except the edge vertices
    for (unsigned i = 0; i < 4; ++i) {
      unsigned idx = c1->vertex(i)->index();
      if (idx != v1 && idx != v2) {
        face_vertices.push_back(idx);
      }
    }
    for (unsigned i = 0; i < 4; ++i) {
      unsigned idx = c2->vertex(i)->index();
      if (idx != v1 && idx != v2) {
        face_vertices.push_back(idx);
      }
    }

    // Calculate edge length
    double edge_length = std::sqrt(rt.segment(*eit).squared_length());

    // Add face to mesh
    mesh.push_back(face_vertices, edge_length);
  }

  return mesh;
}
